	m_distance = zdb::CWorld::m_world->m_camera->m_far_plane;
	m_node = NULL;
	m_perturbPositionX.m_min = 0.0f;
	m_perturbPositionX.m_max = 0.0f;
	m_perturbPositionY.m_min = 0.0f;
	m_perturbPositionY.m_max = 0.0f;
